const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/client\"\n}\n\n// ----------------------------------------------------\n// 1. OUTLETS & BRANDS (سول ميت كافيه & حلواني أبو عادل)\n// ----------------------------------------------------\nmodel Outlet {\n  id        String   @id @default(cuid())\n  name      String // \"سول ميت كافيه (Soulmate Cafe)\" | \"حلواني أبو عادل (Abu Adel Patisserie)\"\n  code      String   @unique // \"SOULMATE_CAFE\" | \"ABU_ADEL_PATISSERIE\"\n  type      String   @default(\"CAFE\") // \"CAFE\" | \"PASTRY_SHOP\"\n  address   String\n  phone     String\n  whatsapp  String?\n  logoUrl   String?\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  users        User[]\n  tables       DiningTable[]\n  menuItems    MenuItem[]\n  rawMaterials RawMaterial[]\n  orders       Order[]\n  shifts       Shift[]\n  expenses     Expense[]\n  reservations Reservation[]\n  chatMessages ChatMessage[]\n}\n\n// ----------------------------------------------------\n// 2. USERS, ROLES & PERMISSIONS (المستخدمين وطاقم العمل)\n// ----------------------------------------------------\nmodel User {\n  id           String   @id @default(cuid())\n  name         String\n  username     String   @unique\n  passwordHash String\n  pin          String   @default(\"159920\") // PIN code for quick cashier / POS switches\n  phone        String?\n  role         String   @default(\"cashier\") // owner, general_manager, branch_manager, cashier, barista, chef, waiter\n  outletId     String?\n  outlet       Outlet?  @relation(fields: [outletId], references: [id], onDelete: SetNull)\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 3. DINING TABLES & ZONES (ترابيزات كافيه سول ميت)\n// ----------------------------------------------------\nmodel DiningTable {\n  id            String   @id @default(cuid())\n  outletId      String\n  outlet        Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  tableNumber   String // \"T-01\", \"T-02\", \"VIP-1\", \"TERRACE-2\"\n  zone          String   @default(\"INDOOR\") // \"INDOOR\", \"OUTDOOR\", \"VIP_LOUNGE\"\n  capacity      Int      @default(4)\n  status        String   @default(\"AVAILABLE\") // \"AVAILABLE\", \"OCCUPIED\", \"BILL_REQUESTED\", \"RESERVED\"\n  activeOrderId String?\n  qrCodeUrl     String?\n  isActive      Boolean  @default(true)\n  createdAt     DateTime @default(now())\n\n  orders Order[]\n}\n\n// ----------------------------------------------------\n// 4. MENU ITEMS & FINISHED GOODS (أصناف الكافيه وحلواني أبو عادل)\n// ----------------------------------------------------\nmodel MenuItem {\n  id                    String   @id @default(cuid())\n  outletId              String\n  outlet                Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  nameAr                String\n  nameEn                String?\n  category              String // HOT_COFFEE, COLD_COFFEE, BEVERAGES, WAFFLES_PANCAKES, ORIENTAL_SWEETS, WESTERN_PASTRY, CAKES_TORTES, ICE_CREAM, GIFT_BOXES\n  price                 Float\n  costPrice             Float    @default(0) // Calculated from Recipe or purchase cost\n  durationMinutes       Int      @default(5)\n  description           String?\n  image                 String?\n  itemType              String   @default(\"PREPARED_BEVERAGE\") // \"PREPARED_BEVERAGE\" (uses recipe) | \"READY_PASTRY\" (finished unit) | \"RETAIL\"\n  unitType              String   @default(\"PIECE\") // \"PIECE\", \"PORTION\", \"KG\", \"BOX\"\n  stockQty              Int      @default(100) // For ready-made pastries, tortes, boxes\n  minStockAlert         Int      @default(10)\n  isAvailable           Boolean  @default(true)\n  sortOrder             Int      @default(0)\n  loyaltyPointsEarned   Int      @default(5)\n  loyaltyPointsRequired Int      @default(50)\n  createdAt             DateTime @default(now())\n\n  recipes RecipeItem[]\n}\n\n// ----------------------------------------------------\n// 5. RAW MATERIALS INVENTORY (خامات البار ومخزن المشروبات)\n// ----------------------------------------------------\nmodel RawMaterial {\n  id            String   @id @default(cuid())\n  outletId      String\n  outlet        Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  nameAr        String // بن إسبريسو حبوب، حليب كامل الدسم، سيرب فانيليا، صوص لوتس، أكواب ورقية\n  unit          String   @default(\"GRAM\") // \"GRAM\", \"ML\", \"PIECE\", \"PUMP\"\n  currentStock  Float    @default(1000)\n  minStockAlert Float    @default(200)\n  costPerUnit   Float    @default(0.5) // EGP per Gram or ML\n  supplierName  String?\n  notes         String?\n  updatedAt     DateTime @default(now()) @updatedAt\n\n  recipeUsage RecipeItem[]\n}\n\n// ----------------------------------------------------\n// 6. RECIPES & BILL OF MATERIALS (الريسيبي وخصم الخامات)\n// ----------------------------------------------------\nmodel RecipeItem {\n  id            String      @id @default(cuid())\n  menuItemId    String\n  menuItem      MenuItem    @relation(fields: [menuItemId], references: [id], onDelete: Cascade)\n  rawMaterialId String\n  rawMaterial   RawMaterial @relation(fields: [rawMaterialId], references: [id], onDelete: Cascade)\n  qtyRequired   Float // 18 grams, 160 ml, 1 piece\n  createdAt     DateTime    @default(now())\n\n  @@unique([menuItemId, rawMaterialId])\n}\n\n// ----------------------------------------------------\n// 7. CUSTOMERS & LOYALTY CRM (قاعدة العملاء وبرنامج الولاء)\n// ----------------------------------------------------\nmodel Customer {\n  id               String   @id @default(cuid())\n  name             String\n  phone            String   @unique\n  email            String?\n  passwordHash     String?\n  isVerified       Boolean  @default(false)\n  verificationCode String?\n  address          String?\n  city             String?\n  loyaltyPoints    Int      @default(0)\n  totalSpent       Float    @default(0)\n  visitCount       Int      @default(0)\n  notes            String?\n  createdAt        DateTime @default(now())\n\n  orders Order[]\n}\n\n// ----------------------------------------------------\n// 8. ORDERS & TICKETS (الطلبات والشيكات والفواتير)\n// ----------------------------------------------------\nmodel Order {\n  id              String       @id @default(cuid())\n  outletId        String\n  outlet          Outlet       @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  orderNumber     String       @unique // \"SOUL-1001\" or \"ADEL-1001\"\n  orderType       String       @default(\"DINE_IN\") // \"DINE_IN\", \"TAKEAWAY\", \"DELIVERY\"\n  tableId         String?\n  table           DiningTable? @relation(fields: [tableId], references: [id], onDelete: SetNull)\n  tableNumber     String?\n  deliveryAddress String?\n  deliveryPhone   String?\n  deliveryNotes   String?\n  status          String       @default(\"NEW_PENDING\") // \"NEW_PENDING\", \"PREPARING\", \"READY_TO_SERVE\", \"COMPLETED\", \"CANCELLED\"\n  paymentStatus   String       @default(\"PENDING\") // \"PENDING\", \"PAID\"\n  paymentMethod   String       @default(\"CASH\") // \"CASH\", \"CARD\", \"INSTAPAY\", \"VODAFONE_CASH\", \"SPLIT\"\n\n  subtotal       Float @default(0)\n  serviceCharge  Float @default(0)\n  taxAmount      Float @default(0)\n  discountAmount Float @default(0)\n  tipAmount      Float @default(0)\n  finalAmount    Float @default(0)\n\n  cashierName   String?\n  waiterName    String?\n  customerName  String?\n  customerPhone String?\n  customerId    String?\n  customer      Customer? @relation(fields: [customerId], references: [id], onDelete: SetNull)\n\n  pointsEarned   Int     @default(0)\n  pointsRedeemed Int     @default(0)\n  notes          String?\n  items          String // JSON Array of ordered items [{ menuItemId, nameAr, price, qty, notes, itemType }]\n\n  createdAt DateTime  @default(now())\n  settledAt DateTime?\n\n  kdsTickets KdsTicket[]\n}\n\n// ----------------------------------------------------\n// 9. KDS (KITCHEN & BARISTA DISPLAY SYSTEM - شاشة المطبخ والبار)\n// ----------------------------------------------------\nmodel KdsTicket {\n  id           String    @id @default(cuid())\n  orderId      String\n  order        Order     @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  station      String    @default(\"BARISTA\") // \"BARISTA\", \"KITCHEN\", \"PASTRY_COUNTER\"\n  itemsSummary String // JSON or formatted string of items for this station\n  status       String    @default(\"QUEUED\") // \"QUEUED\", \"IN_PREPARATION\", \"DONE\"\n  createdAt    DateTime  @default(now())\n  completedAt  DateTime?\n}\n\n// ----------------------------------------------------\n// 10. SHIFTS & CASH REGISTER (الورديات والخزنة وتقفيل الدرج)\n// ----------------------------------------------------\nmodel Shift {\n  id               String  @id @default(cuid())\n  outletId         String\n  outlet           Outlet  @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  shiftNumber      Int     @default(1)\n  openedBy         String // Cashier name\n  closedBy         String?\n  openingCashFloat Float   @default(500) // فكة الدرج الافتتاحية\n  expectedCash     Float   @default(0)\n  actualCash       Float   @default(0)\n  difference       Float   @default(0) // Actual - Expected\n\n  cashCollected     Float @default(0)\n  visaCollected     Float @default(0)\n  instapayCollected Float @default(0)\n  vodafoneCollected Float @default(0)\n  totalRevenue      Float @default(0)\n  expensesTotal     Float @default(0)\n  ticketsCount      Int   @default(0)\n\n  handedTo String? // المالك أو مدير الفرع المستلم\n  notes    String?\n  status   String    @default(\"OPEN\") // \"OPEN\", \"CLOSED\"\n  openedAt DateTime  @default(now())\n  closedAt DateTime?\n}\n\n// ----------------------------------------------------\n// 11. EXPENSES & PETTY CASH (المصروفات والنثريات اليومية)\n// ----------------------------------------------------\nmodel Expense {\n  id         String   @id @default(cuid())\n  outletId   String\n  outlet     Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  title      String\n  amount     Float\n  category   String   @default(\"SUPPLIES\") // \"RAW_MATERIALS\", \"SUPPLIES\", \"MAINTENANCE\", \"SALARIES\", \"UTILITIES\", \"MISC\"\n  recordedBy String\n  notes      String?\n  createdAt  DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 12. SYSTEM SETTINGS & LOYALTY TOGGLE (الإعدادات العامة والولاء)\n// ----------------------------------------------------\nmodel SystemSettings {\n  id            String @id @default(\"default-settings\")\n  brandNameAr   String @default(\"مجموعة أبو عادل وسول ميت كافيه (حلواني & كافيه عصري)\")\n  brandNameEn   String @default(\"ABU ADEL PATISSERIE & SOULMATE CAFE\")\n  soulmatePhone String @default(\"01099887766\")\n  abuAdelPhone  String @default(\"15992\")\n  hotline       String @default(\"15992\")\n  whatsapp      String @default(\"01099887766\")\n  haliyomakUrl  String @default(\"https://haliyomak.com/\")\n  facebookUrl   String @default(\"https://www.facebook.com/hashtag/soulmate_cafe\")\n\n  serviceChargePercent   Float   @default(12.0)\n  taxPercent             Float   @default(14.0)\n  isServiceChargeEnabled Boolean @default(false)\n  isTaxEnabled           Boolean @default(false)\n\n  // 👑 زر تفعيل / تعطيل برنامج الولاء في أي وقت\n  isLoyaltyEnabled    Boolean @default(true)\n  pointsPerPoundSpent Float   @default(0.1) // 1 point per 10 EGP\n  poundValuePerPoint  Float   @default(0.5) // Each point = 0.5 EGP\n\n  receiptFooterNotes String   @default(\"شكراً لزيارتكم حلواني أبو عادل وسول ميت كافيه • حلي يومك واستمتع بقهوتك ☕🍰\")\n  systemLocked       Boolean  @default(false)\n  lockMessage        String   @default(\"النظام مغلق مؤقتاً لأعمال الجرد والصيانة الدورية.\")\n  updatedAt          DateTime @default(now()) @updatedAt\n}\n\n// ----------------------------------------------------\n// 13. RESERVATIONS & EVENT BOOKINGS (حجز الترابيزات والحفلات)\n// ----------------------------------------------------\nmodel Reservation {\n  id              String   @id @default(cuid())\n  outletId        String\n  outlet          Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  customerName    String\n  customerPhone   String\n  customerEmail   String?\n  reservationType String   @default(\"TABLE\") // \"TABLE\" (ترابيزة عادية) | \"PARTY\" (حفلة / عيد ميلاد / مناسبة)\n  guestCount      Int      @default(2)\n  bookingDate     DateTime\n  timeSlot        String // \"07:00 PM\"\n  zonePreference  String? // \"INDOOR\", \"OUTDOOR_TERRACE\", \"VIP_LOUNGE\"\n  specialRequests String?\n  status          String   @default(\"PENDING\") // \"PENDING\", \"CONFIRMED\", \"CANCELLED\", \"COMPLETED\"\n  createdAt       DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 14. INTERNAL LIVE CHAT (الشات الداخلي بين الزبون والباريستا/الإدارة)\n// ----------------------------------------------------\nmodel ChatMessage {\n  id          String   @id @default(cuid())\n  outletId    String\n  outlet      Outlet   @relation(fields: [outletId], references: [id], onDelete: Cascade)\n  senderType  String // \"CUSTOMER\" | \"STAFF\"\n  senderName  String\n  senderPhone String?\n  tableNumber String?\n  orderNumber String?\n  message     String\n  isRead      Boolean  @default(false)\n  createdAt   DateTime @default(now())\n}\n"
}

